import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 53 An interesting climate","description":"学习 频率副词与天气动词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 53 An interesting climate","description":"学习 频率副词与天气动词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 频率副词与天气动词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 52 Where do they come from?","link":"/life/english/new-concept/book-1/unit-03/lesson-052"},"next":{"text":"第一册：英语初阶 · Lesson 54 What nationality are they?","link":"/life/english/new-concept/book-1/unit-03/lesson-054"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 52 Where do they come from?","link":"/life/english/new-concept/book-1/unit-03/lesson-052"},"next":{"text":"第一册：英语初阶 · Lesson 54 What nationality are they?","link":"/life/english/new-concept/book-1/unit-03/lesson-054"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/lesson-053.md","filePath":"life/english/new-concept/book-1/unit-03/lesson-053.md"}'),o={name:"life/english/new-concept/book-1/unit-03/lesson-053.md"};function s(l,e,r,h,c,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第一册-英语初阶-·-lesson-53-an-interesting-climate" tabindex="-1">第一册：英语初阶 · Lesson 53 An interesting climate <a class="header-anchor" href="#第一册-英语初阶-·-lesson-53-an-interesting-climate" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 53 An interesting climate&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元 3</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-054">配套课 Lesson 54</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>比较季节天气并询问来自哪里 本课要掌握频率副词与天气动词，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>weather</td><td>/ˈweðə/</td><td>n.</td><td>天气</td><td>cold weather</td></tr><tr><td>rain</td><td>/reɪn/</td><td>v.</td><td>下雨</td><td>it rains</td></tr><tr><td>windy</td><td>/ˈwɪndi/</td><td>adj.</td><td>有风的</td><td>a windy day</td></tr><tr><td>often</td><td>/ˈɒfn/</td><td>adv.</td><td>经常</td><td>often travel</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>it often rains — 常见天气规律</li><li>be usually warm — 频率副词放 be 后</li></ul><h2 id="语法讲解-频率副词与天气动词" tabindex="-1">语法讲解：频率副词与天气动词 <a class="header-anchor" href="#语法讲解-频率副词与天气动词" aria-label="Permalink to &quot;语法讲解：频率副词与天气动词&quot;">​</a></h2><p>always、usually、often、sometimes、never 表频率，通常位于实义动词前、be 后。It often rains 中 rain 是动词；It is often rainy 中 rainy 是形容词。频率不等于眼前进行：often rains 描述规律，is raining 描述此刻。never 已含否定意义，在标准英语中通常不再配 don&#39;t。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>It often rains in this coastal town.</p></blockquote><p>这座沿海小镇经常下雨。</p><p>It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>often 在 be 后、普通动词前是常见位置；不要机械认为所有副词都放句尾。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“It often rains in this coastal town.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>It often rains in this coastal town. The evenings are usually cool in autumn.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“比较季节天气并询问来自哪里”写两至三句，再读给同伴听。至少使用一次频率副词与天气动词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。 The evenings 是复数主语，are 后放 usually，cool 作表语；in autumn 表季节。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 rain/rains：It often ___ here.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rains</p><p><strong>解析：</strong> 按本课规则判断：always、usually、often、sometimes、never 表频率，通常位于实义动词前、be 后。It often rains 中 rain 是动词；It is often rainy 中 rainy 是形容词。频率不等于眼前进行：often rains 描述规律，is raining 描述此刻。never 已含否定意义，在标准英语中通常不再配 don&#39;t。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“这座沿海小镇经常下雨。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> It often rains in this coastal town.</p><p><strong>解析：</strong> It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：The evenings are usually cool in autumn.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 秋天的夜晚通常凉爽。</p><p><strong>解析：</strong> The evenings 是复数主语，are 后放 usually，cool 作表语；in autumn 表季节。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：频率副词与天气动词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-052">上一课</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-054">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(o,[["render",s]]);export{p as __pageData,f as default};
